namespace ghidra.app.plugin.core.datamgr.actions;



using docking;
using docking.action;
using docking.action;
using docking.widgets.tree;
using docking.widgets.tree;
using ghidra.app.cmd.function;
using ghidra.app.plugin.core.datamgr;
using ghidra.app.plugin.core.datamgr;
using ghidra.app.plugin.core.datamgr.tree;
using ghidra.framework.plugintool;
using ghidra.program.model.listing;
using ghidra.program.model.symbol;

public class ApplyFunctionDataTypesAction : DockingAction {

	private DataTypeManagerPlugin plugin;

	public ApplyFunctionDataTypesAction(DataTypeManagerPlugin plugin) : base("Apply Function Data Types", plugin.getName())
    {
		this.plugin = plugin;

		setPopupMenuData(new MenuData(new string[] { "Apply Function Data Types" }, null,
			"VeryLast"));

		setEnabled(true);
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		if (plugin.getProgram() == null) {
			return false;
		}

		if (!(context is DataTypesActionContext)) {
			return false;
		}

		object contextObject = context.getContextObject();
		GTree gTree = (GTree) contextObject;
		TreePath[] selectionPaths = gTree.getSelectionPaths();
		if (selectionPaths.length != 1) {
			return false;
		}

		GTreeNode node = (GTreeNode) selectionPaths[0].getLastPathComponent();

		if (node is CategoryNode) {
			CategoryNode catNode = (CategoryNode) node;
			node = catNode.getArchiveNode();
		}

		return (node is FileArchiveNode) || (node is ProjectArchiveNode) ||
			(node is ProgramArchiveNode);
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {
		GTree gTree = (GTree) context.getContextObject();
		TreePath selectionPath = gTree.getSelectionPath();
		CategoryNode node = (CategoryNode) selectionPath.getLastPathComponent();

		Program program = plugin.getProgram();
		ApplyFunctionDataTypesCmd cmd =
			new ApplyFunctionDataTypesCmd(node.getCategory(), null, SourceType.USER_DEFINED, true,
				true);
		PluginTool tool = plugin.getTool();
		tool.executeBackgroundCommand(cmd, program);
	}
}
